//! Файл: settings/catalog/feed_watch.rs
//! Что делает: настройки сторожа пар и соединений стаканов (решение 202, core/feed_watch.rs). Значений нет; любая не
//! задана у площадки — сторож площадки выключен (причина — в журнале). Советы Тиграна — docs/FIRST_RUN.md.
//! Решение 213: подтверждение тихой пары по REST (venue.quiet_confirm_*) — не задана — подтверждения нет, тихие пары
//! только в журнале (у бирж с кадрами по расписанию — переподписка по решению 202).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Сторож пар»).

use super::{GV, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 202 и 213. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static FEED_WATCH: &[SettingDef] = &[
    d("Сторож пар", "venue.pair_dead_mult", K::Integer, L::Positive, "раз", GV, "Решение 202: пара молчит, если при живом соединении (кадр не старше feed.stale_after_ms) по ней нет кадра стакана дольше venue.book_stale_ms × это число. Решение 213: молчащую пару сторож подтверждает у биржи по REST (venue.quiet_confirm_*) — книга не менялась — тихая, не переподписывается; новее — кадры потеряны, переподписка. Без подтверждения переподписка — только у бирж, где по документации кадры идут по расписанию без изменений").optional(),
    d("Сторож пар", "venue.feed_warmup_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: прогрев — после начала сессии соединения (старт бота, переподключение) и после переподписки пары она не считается мёртвой столько мс: при ребуте, пока потоки оживают, ничего не дёргается").optional(),
    d("Сторож пар", "venue.pair_resub_attempts", K::Integer, L::Positive, "попыток", GV, "Решение 202: сколько раз подряд переподписать мёртвую пару в одном круге (только её — отписка + подписка, соседи по соединению не трогаются)").optional(),
    d("Сторож пар", "venue.pair_resub_interval_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: промежуток между попытками переподписки пары в круге; с этой же частотой сторож смотрит свежесть пар").optional(),
    d("Сторож пар", "venue.pair_resub_pause_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: пауза после круга попыток, если пара не ожила; потом новый круг").optional(),
    d("Сторож пар", "venue.conn_dead_pct", K::Integer, L::Positive, "%", GV, "Решение 202: если в соединении (пачке пар) мёртвых пар после двух неудачных кругов больше этой доли и по его парам нет идущей сделки — переподключается только это соединение; есть сделка — не переподключается, уведомление venue.feed_conn_blocked").optional(),
    d("Сторож пар", "venue.conn_reconnect_min_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: следующее переподключение того же соединения сторожем — не раньше, чем через столько мс (защита от цикла)").optional(),
    d("Сторож пар", "venue.conn_reconnect_max_per_hour", K::Integer, L::Positive, "раз", GV, "Решение 202: больше стольких переподключений одного соединения за час — больше не переподключаем, журнал и уведомление venue.feed_conn_giveup («нужен человек»)").optional(),
    d("Сторож пар", "venue.quiet_confirm_min_ms", K::Integer, L::Positive, "мс", GV, "Решение 213: молчащую пару (тишина дольше venue.book_stale_ms × venue.pair_dead_mult) сторож проверяет по REST не чаще раза в столько мс: книга на бирже не менялась с последнего кадра (Gate — по номеру книги; Bybit — по номеру u при venue.depth_levels = 1000; MEXC, Bitget, Bybit, KuCoin, BingX, OKX, CoinEx, Poloniex, Kraken, HTX, Phemex — первые venue.depth_levels уровней ответа REST равны стакану в памяти) — пара тихая, подтверждена, не переподписывается, а её стакан считается свежим для расчёта и котировки до следующей проверки (столько мс + venue.pair_resub_interval_ms от запроса); новее — кадры потеряны, переподписка. Не задана — подтверждения нет (журнал)").optional(),
    d("Сторож пар", "venue.quiet_confirm_max_per_s", K::Integer, L::Positive, "запросов/с", GV, "Решение 213: не больше стольких REST-запросов подтверждения тихих пар в секунду на площадку (свой лимит публичных запросов биржи — в её документации; Gate: 200 за 10 с на IP на все публичные запросы; MEXC: вес 3 из корзины IP 300 за 10 с; Bitget: 20 запросов/с на IP вместе с котировками исполнения; Bybit: 600 запросов за 5 с на IP на все запросы; KuCoin: вес 2 из квоты Public за 30 с; BingX: 500 запросов за 10 с на IP; OKX: 40 запросов за 2 с на IP на GET /api/v5/market/books; CoinEx: частоты GET /v2/spot/depth нет, IP — 400 запросов/с на все; Poloniex: у Order Book в таблице лимитов пусто, рыночные — по IP, /markets/{symbol} — 200/с; Kraken: лимит публичных запросов в документации не описан; HTX: частота GET /market/depth в документации не указана; Phemex: частоты GET /md/orderbook нет, IP — 5000 запросов за 5 мин на все, превышение — блок IP на 5 мин). Не хватает — проверки откладываются, стакан тихой пары без подтверждения устаревает. Не задана — подтверждения нет (журнал)").optional(),
];
